import { CustomStore } from 'frontend/types'
import { AccountProvider } from 'common/types/connectedAccounts'

export interface ConnectedAccountStoreConfig extends CustomStore {
  aliases: string[]
}

export const CONNECTED_ACCOUNT_STORES: Record<AccountProvider, ConnectedAccountStoreConfig> = {
  xbox: {
    id: "store-1782835258378",
    name: "Xbox",
    icon: "data:image/png;base64,",
    isVisible: true,
    aliases: ['xbox']
  },
  ea: {
    id: "store-1782833766006",
    name: "EA Games",
    icon: "data:image/png;base64,",
    isVisible: true,
    aliases: ['ea', 'ea app', 'ea games', 'origin']
  },
  battlenet: {
    id: "store-1790309300464",
    name: "Battle.net",
    icon: "data:image/png;base64,",
    isVisible: true,
    aliases: ['battlenet', 'battle.net', 'blizzard']
  },
  ubisoft: {
    id: "store-1790309448685",
    name: "Ubisoft",
    icon: "data:image/png;base64,",
    isVisible: true,
    aliases: ['ubisoft', 'ubisoft connect', 'uplay']
  }
}

/**
 * Garante que a loja personalizada para o provedor de conta conectada exista em 'heroic_custom_stores'.
 * Caso não exista, cria-a automaticamente com o nome e ícone oficiais configurados nesta build.
 * Retorna o ID da loja correspondente.
 */
export function ensureConnectedAccountCustomStore(provider: AccountProvider): string {
  try {
    const config = CONNECTED_ACCOUNT_STORES[provider]
    if (!config) return provider

    const rawCustomStores = localStorage.getItem('heroic_custom_stores') || '[]'
    let customStores: CustomStore[] = []
    try {
      customStores = JSON.parse(rawCustomStores)
      if (!Array.isArray(customStores)) customStores = []
    } catch {
      customStores = []
    }

    const aliases = config.aliases.map((a) => a.toLowerCase())
    const existingIndex = customStores.findIndex((s) => {
      const nameLower = (s.name || '').toLowerCase()
      const idLower = (s.id || '').toLowerCase()
      return s.id === config.id || aliases.includes(nameLower) || aliases.includes(idLower)
    })

    if (existingIndex >= 0) {
      const existing = customStores[existingIndex]
      // Se não possui ícone ou o ícone estava vazio, preserva o ícone oficial
      if (!existing.icon && config.icon) {
        existing.icon = config.icon
        localStorage.setItem('heroic_custom_stores', JSON.stringify(customStores))
        window.dispatchEvent(new Event('customStoresChanged'))
        window.dispatchEvent(new StorageEvent('storage', { key: 'heroic_custom_stores' }))
      }
      return existing.id
    }

    // A loja não existe: cria automaticamente com o nome e ícone oficiais
    const newStore: CustomStore = {
      id: config.id,
      name: config.name,
      icon: config.icon,
      isVisible: true
    }

    customStores.push(newStore)
    localStorage.setItem('heroic_custom_stores', JSON.stringify(customStores))
    window.dispatchEvent(new Event('customStoresChanged'))
    window.dispatchEvent(new StorageEvent('storage', { key: 'heroic_custom_stores' }))

    return newStore.id
  } catch (error) {
    console.error('[ConnectedAccountStores] Erro ao garantir loja para ' + provider + ':', error)
    return provider
  }
}
